-- Game ON migration 0007: marketplace notifications and download analytics.
-- Notification rows are generated by trusted database triggers. Download events
-- are written by the server-side Store download endpoint only.

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  notification_type text not null check (notification_type in ('game_published','build_update','download_ready','system')),
  title text not null check (char_length(title) between 1 and 120),
  message text not null check (char_length(message) between 1 and 500),
  entity_type text,
  entity_id uuid,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists notifications_user_created_idx on public.notifications(user_id, created_at desc);
alter table public.notifications enable row level security;
create policy "notifications_read_own" on public.notifications for select to authenticated using (user_id = auth.uid());
create policy "notifications_mark_own_read" on public.notifications for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
-- No client insert/delete policy: trusted triggers and server-side service role create notifications.

create table if not exists public.download_events (
  id bigint generated always as identity primary key,
  user_id uuid references auth.users(id) on delete set null,
  game_id uuid not null references public.games(id) on delete restrict,
  build_id uuid not null references public.game_builds(id) on delete restrict,
  platform text not null check (platform in ('android','windows','web')),
  created_at timestamptz not null default now()
);
create index if not exists download_events_game_created_idx on public.download_events(game_id, created_at desc);
create index if not exists download_events_build_created_idx on public.download_events(build_id, created_at desc);
alter table public.download_events enable row level security;
-- No client policies. Only trusted server-side code can write/read raw download events.

create or replace function public.notify_studio_when_game_published()
returns trigger language plpgsql security definer set search_path = '' as $$
declare studio_owner uuid;
begin
  if new.status = 'published' and old.status is distinct from new.status then
    select owner_user_id into studio_owner from public.developer_studios where id = new.studio_id;
    if studio_owner is not null then
      insert into public.notifications(user_id, notification_type, title, message, entity_type, entity_id)
      values (studio_owner, 'game_published', 'Your game is live', new.title || ' has been published on Game ON Store.', 'game', new.id);
    end if;
  end if;
  return new;
end; $$;
drop trigger if exists games_notify_published on public.games;
create trigger games_notify_published after update of status on public.games
for each row execute function public.notify_studio_when_game_published();

create or replace function public.notify_players_when_build_approved()
returns trigger language plpgsql security definer set search_path = '' as $$
declare game_title text;
begin
  if new.release_status = 'approved' and old.release_status is distinct from new.release_status
     and new.scan_status = 'clean' and new.upload_status = 'uploaded' then
    select title into game_title from public.games where id = new.game_id;
    insert into public.notifications(user_id, notification_type, title, message, entity_type, entity_id)
    select ul.user_id, 'build_update', 'Game update available', coalesce(game_title, 'A game in your library') || ' has a new approved build.', 'game_build', new.id
    from public.user_library ul where ul.game_id = new.game_id;
  end if;
  return new;
end; $$;
drop trigger if exists builds_notify_players on public.game_builds;
create trigger builds_notify_players after update of release_status on public.game_builds
for each row execute function public.notify_players_when_build_approved();

comment on table public.notifications is 'User-visible notifications. Inserts are restricted to trusted database triggers and server-side service role.';
comment on table public.download_events is 'Server-only download-link issuance analytics; this records link issuance, not confirmed completed transfers.';
